from fastapi import Depends, HTTPException
from typing import List, Optional
from ..middleware.auth_middleware import get_current_user
from ..core.exceptions import ForbiddenException


class CurrentUser:
    """Represents the authenticated user injected into requests."""

    def __init__(
        self,
        id: str,
        email: str,
        full_name: str,
        role: str,
        roles: List[str],
        primary_role: str,
        is_active: bool = True,
        is_admin_approved: bool = False,
        is_verified: bool = False,
    ):
        self.id = id
        self.email = email
        self.full_name = full_name
        self.role = role
        self.roles = roles
        self.primary_role = primary_role
        self.is_active = is_active
        self.is_admin_approved = is_admin_approved
        self.is_verified = is_verified

    def has_role(self, role: str) -> bool:
        return role in self.roles

    def has_any_role(self, roles: List[str]) -> bool:
        return bool(set(self.roles) & set(roles))

    @property
    def is_admin(self) -> bool:
        return self.has_any_role(["super_admin", "admin"])

    @property
    def is_doctor(self) -> bool:
        return self.has_role("doctor")

    @property
    def is_patient(self) -> bool:
        return self.has_any_role(["patient", "client"])

    @property
    def is_hospital(self) -> bool:
        return self.has_any_role(["hospital", "hospital_admin"])

    @property
    def is_pharmacy(self) -> bool:
        return self.has_any_role(["pharmacy", "pharmacy_admin"])

    @property
    def is_blood_donor(self) -> bool:
        return self.has_role("blood_donor")


def require_role(*allowed_roles: str):
    """
    FastAPI dependency that enforces role-based access control.
    Usage: @router.get("/", dependencies=[Depends(require_role("admin", "super_admin"))])
    """
    async def role_checker(current_user: CurrentUser = Depends(get_current_user)) -> CurrentUser:
        if not current_user.is_active:
            raise ForbiddenException("Account is deactivated")
        if not current_user.has_any_role(list(allowed_roles)):
            raise ForbiddenException(
                f"Access denied. Required role: {', '.join(allowed_roles)}"
            )
        return current_user

    return role_checker


def require_admin():
    """Shortcut for admin-only endpoints."""
    return require_role("super_admin", "admin")


def require_doctor():
    """Shortcut for doctor-only endpoints."""
    return require_role("doctor")


def require_patient():
    """Shortcut for patient/client endpoints."""
    return require_role("patient", "client")


def require_hospital():
    """Shortcut for hospital endpoints."""
    return require_role("hospital", "hospital_admin")


def require_pharmacy():
    """Shortcut for pharmacy endpoints."""
    return require_role("pharmacy", "pharmacy_admin")


def require_verified():
    """
    Dependency that requires the user to be verified.
    Can be combined with require_role using multiple dependencies.
    """
    async def verification_checker(current_user: CurrentUser = Depends(get_current_user)) -> CurrentUser:
        if not current_user.is_verified:
            raise ForbiddenException("Email verification required")
        return current_user

    return verification_checker


def require_approved():
    """
    Dependency that requires the user to be admin-approved.
    Used for doctors, hospitals, pharmacies who need approval.
    """
    async def approval_checker(current_user: CurrentUser = Depends(get_current_user)) -> CurrentUser:
        if not current_user.is_admin_approved:
            raise ForbiddenException("Admin approval required")
        return current_user

    return approval_checker

from fastapi import HTTPException
from typing import Optional, Any


class AppException(HTTPException):
    """Base application exception."""

    def __init__(
        self,
        message: str = "An error occurred",
        status_code: int = 400,
        details: Optional[Any] = None,
    ):
        super().__init__(status_code=status_code, detail=message)
        self.message = message
        self.details = details


class NotFoundException(AppException):
    def __init__(self, message: str = "Resource not found"):
        super().__init__(message=message, status_code=404)


class UnauthorizedException(AppException):
    def __init__(self, message: str = "Unauthorized access"):
        super().__init__(message=message, status_code=401)


class ForbiddenException(AppException):
    def __init__(self, message: str = "You do not have permission to perform this action"):
        super().__init__(message=message, status_code=403)


class ConflictException(AppException):
    def __init__(self, message: str = "Resource already exists"):
        super().__init__(message=message, status_code=409)


class BadRequestException(AppException):
    def __init__(self, message: str = "Bad request", details: Optional[Any] = None):
        super().__init__(message=message, status_code=400, details=details)


class ValidationException(AppException):
    def __init__(self, message: str = "Validation error", details: Optional[Any] = None):
        super().__init__(message=message, status_code=422, details=details)


class RateLimitException(AppException):
    def __init__(self, message: str = "Too many requests. Please try again later."):
        super().__init__(message=message, status_code=429)


class InternalServerException(AppException):
    def __init__(self, message: str = "Internal server error"):
        super().__init__(message=message, status_code=500)

from typing import Optional
import uuid
from math import ceil


def generate_uuid() -> str:
    return str(uuid.uuid4())


def paginate(page: int = 1, size: int = 20) -> dict:
    return {"offset": (page - 1) * size, "limit": size}


def calculate_pages(total: int, size: int) -> int:
    """Calculate total number of pages."""
    if size <= 0:
        return 0
    return ceil(total / size)


def build_pagination_meta(total: int, page: int, size: int) -> dict:
    """Build pagination metadata for API responses."""
    return {
        "total": total,
        "page": page,
        "size": size,
        "pages": calculate_pages(total, size),
    }


def generate_order_number(prefix: str = "ORD") -> str:
    """Generate a unique order number."""
    import time
    return f"{prefix}-{int(time.time())}-{uuid.uuid4().hex[:6].upper()}"


def generate_request_number(prefix: str = "REQ") -> str:
    """Generate a unique request number."""
    import time
    return f"{prefix}-{int(time.time())}-{uuid.uuid4().hex[:6].upper()}"

from pydantic import field_validator
import re
from typing import Optional


def validate_phone(value: Optional[str]) -> Optional[str]:
    """Validate phone number format."""
    if value is None:
        return value
    cleaned = re.sub(r'[\s\-\(\)]', '', value)
    if not re.match(r'^\+?\d{7,15}$', cleaned):
        raise ValueError('Invalid phone number format')
    return cleaned


def validate_blood_group(value: Optional[str]) -> Optional[str]:
    """Validate blood group."""
    if value is None:
        return value
    valid_groups = ['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-']
    if value not in valid_groups:
        raise ValueError(f'Invalid blood group. Must be one of: {valid_groups}')
    return value


def validate_gender(value: Optional[str]) -> Optional[str]:
    """Validate gender value."""
    if value is None:
        return value
    valid = ['male', 'female', 'other', 'prefer-not-to-say']
    if value not in valid:
        raise ValueError(f'Invalid gender. Must be one of: {valid}')
    return value


def validate_role_name(value: str) -> str:
    """Validate role name."""
    valid_roles = [
        'super_admin', 'admin', 'admin_applicant', 'moderator',
        'doctor', 'hospital', 'hospital_admin', 'pharmacy', 'pharmacy_admin',
        'patient', 'client', 'blood_donor', 'emergency_volunteer', 'normal_user',
    ]
    if value not in valid_roles:
        raise ValueError(f'Invalid role. Must be one of: {valid_roles}')
    return value

from datetime import datetime, timedelta
from typing import Optional, Dict, Any
from jose import JWTError, jwt
from passlib.context import CryptContext
from ..config import get_settings
settings = get_settings()
pwd_context = CryptContext(schemes=["bcrypt"], deprecated="auto")
def hash_password(password: str) -> str:
    return pwd_context.hash(password)
def verify_password(plain_password: str, hashed_password: str) -> bool:
    return pwd_context.verify(plain_password, hashed_password)
def create_access_token(data: Dict[str, Any], expires_delta: Optional[timedelta] = None) -> str:
    to_encode = data.copy()
    expire = datetime.utcnow() + (expires_delta or timedelta(minutes=settings.ACCESS_TOKEN_EXPIRE_MINUTES))
    to_encode.update({"exp": expire, "type": "access"})
    return jwt.encode(to_encode, settings.JWT_SECRET_KEY, algorithm=settings.JWT_ALGORITHM)
def create_refresh_token(data: Dict[str, Any]) -> str:
    to_encode = data.copy()
    expire = datetime.utcnow() + timedelta(days=settings.REFRESH_TOKEN_EXPIRE_DAYS)
    to_encode.update({"exp": expire, "type": "refresh"})
    return jwt.encode(to_encode, settings.JWT_SECRET_KEY, algorithm=settings.JWT_ALGORITHM)
def decode_token(token: str) -> Optional[Dict[str, Any]]:
    try:
        return jwt.decode(token, settings.JWT_SECRET_KEY, algorithms=[settings.JWT_ALGORITHM])
    except JWTError:
        return None

// src/services/api.ts

// ============================================
// API CONFIGURATION
// ============================================

const BASE_URL: string =
  import.meta.env.VITE_API_URL || "https://api.medicare.com/v1";

const API_TIMEOUT = 15000;

// ============================================
// TYPES
// ============================================

export interface ApiResponse<T> {
  data: T | null;
  success: boolean;
  message: string;
  statusCode: number;
  timestamp?: string;
}

export interface ApiError {
  message: string;
  statusCode: number;
  errors?: Record<string, string[]>;
}

export interface RequestOptions {
  headers?: HeadersInit;
  timeout?: number;
  skipAuth?: boolean;
}

// ============================================
// HELPERS
// ============================================

const getAuthToken = (): string | null => {
  try {
    const raw = localStorage.getItem("medicare_user");
    if (!raw) return null;

    const parsed = JSON.parse(raw);
    return parsed?.token ?? null;
  } catch {
    return null;
  }
};

// Get user from localStorage
export const getCurrentUser = (): any => {
  try {
    const raw = localStorage.getItem("medicare_user");
    if (!raw) return null;
    return JSON.parse(raw);
  } catch {
    return null;
  }
};

// Save user to localStorage
export const saveUser = (user: any): void => {
  localStorage.setItem("medicare_user", JSON.stringify(user));
};

// Clear user from localStorage
export const clearUser = (): void => {
  localStorage.removeItem("medicare_user");
  localStorage.removeItem("medicare_token");
};

// Simulate network delay (for development)
export const simulateDelay = (ms: number = 800): Promise<void> => {
  if (import.meta.env.PROD && ms > 0) {
    return Promise.resolve();
  }
  return new Promise((resolve) =>
    setTimeout(resolve, ms + Math.random() * 300)
  );
};

// Handle API errors
export const handleApiError = (error: ApiError): void => {
  console.error("API Error:", error);
};

// ============================================
// API CLIENT CLASS
// ============================================

class ApiClient {
  private baseUrl: string;
  private defaultTimeout: number;

  constructor(baseUrl: string, timeout: number = API_TIMEOUT) {
    this.baseUrl = baseUrl;
    this.defaultTimeout = timeout;
  }

  private getHeaders(options?: RequestOptions): HeadersInit {
    const token = !options?.skipAuth ? getAuthToken() : null;

    return {
      "Content-Type": "application/json",
      Accept: "application/json",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...(options?.headers || {}),
    };
  }

  private async handleResponse<T>(
    response: Response,
    endpoint: string
  ): Promise<ApiResponse<T>> {
    const statusCode = response.status;

    if (response.ok) {
      let data: T;
      const contentType = response.headers.get("content-type");
      
      if (contentType?.includes("application/json")) {
        data = await response.json();
      } else {
        data = (await response.text()) as unknown as T;
      }

      return {
        data,
        success: true,
        message: "Success",
        statusCode,
        timestamp: new Date().toISOString(),
      };
    }

    let message = "An unexpected error occurred";
    let errors: Record<string, string[]> | undefined;

    try {
      const err = await response.json();
      message = err?.message || err?.error || message;
      errors = err?.errors;
    } catch {
      try {
        const text = await response.text();
        if (text) message = text;
      } catch {
        // ignore
      }
    }

    if (statusCode === 401) {
      clearUser();
      if (!window.location.pathname.includes("/login")) {
        window.location.href = "/login";
      }
      message = "Session expired. Please login again.";
    }

    if (statusCode === 403) {
      message = "You don't have permission to access this resource.";
    }

    if (statusCode === 404) {
      message = "Resource not found.";
    }

    if (statusCode === 429) {
      message = "Too many requests. Please try again later.";
    }

    if (statusCode >= 500) {
      message = "Server error. Please try again later.";
    }

    return {
      data: null,
      success: false,
      message,
      statusCode,
      timestamp: new Date().toISOString(),
    };
  }

  private async fetchWithTimeout(
    url: string,
    options: RequestInit,
    timeout: number
  ): Promise<Response> {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeout);

    try {
      const response = await fetch(url, {
        ...options,
        signal: controller.signal,
      });
      clearTimeout(timeoutId);
      return response;
    } catch (error) {
      clearTimeout(timeoutId);
      if (error instanceof Error && error.name === "AbortError") {
        throw new Error("Request timeout");
      }
      throw error;
    }
  }

  async request<T>(
    method: string,
    endpoint: string,
    data?: any,
    options?: RequestOptions
  ): Promise<ApiResponse<T>> {
    try {
      const url = `${this.baseUrl}${endpoint}`;
      const headers = this.getHeaders(options);
      const timeout = options?.timeout || this.defaultTimeout;

      const fetchOptions: RequestInit = {
        method,
        headers,
        ...(data && { body: JSON.stringify(data) }),
      };

      const response = await this.fetchWithTimeout(url, fetchOptions, timeout);
      return this.handleResponse<T>(response, endpoint);
    } catch (error: any) {
      console.error(`API ${method} Error [${endpoint}]:`, error);

      let message = "Network error. Please check your connection.";
      
      if (error.message === "Request timeout") {
        message = "Request timeout. Please try again.";
      } else if (error.message?.includes("Failed to fetch")) {
        message = "Unable to connect to server. Please check your internet connection.";
      }

      return {
        data: null,
        success: false,
        message,
        statusCode: 0,
        timestamp: new Date().toISOString(),
      };
    }
  }

  async get<T>(
    endpoint: string,
    params?: Record<string, any>,
    options?: RequestOptions
  ): Promise<ApiResponse<T>> {
    let url = endpoint;
    
    if (params) {
      const searchParams = new URLSearchParams();
      Object.entries(params).forEach(([key, value]) => {
        if (value !== undefined && value !== null && value !== "") {
          searchParams.append(key, String(value));
        }
      });
      const queryString = searchParams.toString();
      if (queryString) {
        url = `${endpoint}?${queryString}`;
      }
    }
    
    return this.request<T>("GET", url, undefined, options);
  }

  async post<T>(
    endpoint: string,
    data?: any,
    options?: RequestOptions
  ): Promise<ApiResponse<T>> {
    return this.request<T>("POST", endpoint, data, options);
  }

  async put<T>(
    endpoint: string,
    data?: any,
    options?: RequestOptions
  ): Promise<ApiResponse<T>> {
    return this.request<T>("PUT", endpoint, data, options);
  }

  async patch<T>(
    endpoint: string,
    data?: any,
    options?: RequestOptions
  ): Promise<ApiResponse<T>> {
    return this.request<T>("PATCH", endpoint, data, options);
  }

  async delete<T>(
    endpoint: string,
    options?: RequestOptions
  ): Promise<ApiResponse<T>> {
    return this.request<T>("DELETE", endpoint, undefined, options);
  }

  async upload<T>(
    endpoint: string,
    file: File,
    fieldName: string = "file",
    additionalData?: Record<string, any>,
    options?: RequestOptions
  ): Promise<ApiResponse<T>> {
    try {
      const formData = new FormData();
      formData.append(fieldName, file);
      
      if (additionalData) {
        Object.entries(additionalData).forEach(([key, value]) => {
          formData.append(key, String(value));
        });
      }

      const token = !options?.skipAuth ? getAuthToken() : null;
      
      const fetchOptions: RequestInit = {
        method: "POST",
        headers: {
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
          ...(options?.headers || {}),
        },
        body: formData,
      };

      const timeout = options?.timeout || this.defaultTimeout;
      const response = await this.fetchWithTimeout(
        `${this.baseUrl}${endpoint}`,
        fetchOptions,
        timeout
      );
      
      return this.handleResponse<T>(response, endpoint);
    } catch (error: any) {
      return {
        data: null,
        success: false,
        message: error?.message || "Upload failed",
        statusCode: 0,
        timestamp: new Date().toISOString(),
      };
    }
  }
}

